// Conservative screening heuristics, not an authority's compliance classifier.
export function assess({width,height,pixels,faceResult,mask,maskWidth,maskHeight,sourceWidth,sourceHeight,upscaled=false}) {
  const rows=[];const add=(id,title,status,detail)=>rows.push({id,title,status,detail});
  add('size','Output dimensions',width===630&&height===810?'pass':'warn',`${width} × ${height} pixels; required output is 630 × 810.`);
  add('resolution','Original image detail',upscaled?'warn':'pass',upscaled?`${sourceWidth} × ${sourceHeight} px original. This crop enlarges the source pixels. Use a higher-resolution original or reduce zoom for better detail.`:`The crop has sufficient source pixels (${sourceWidth} × ${sourceHeight} original).`);
  const faces=faceResult.faceLandmarks||[];
  add('faces','One visible face',faces.length===1?'pass':'warn',faces.length===0?'No face detected. Use a clear, front-facing portrait, or zoom out if the face is cut off.':faces.length>1?'More than one face detected. Crop to include only the applicant.':'One face detected in the crop.');
  const maskAt=(x,y)=>mask?.[Math.min(maskHeight-1,Math.max(0,Math.floor(y*maskHeight)))*maskWidth+Math.min(maskWidth-1,Math.max(0,Math.floor(x*maskWidth)))];
  const rgb=(x,y)=>{const i=(Math.min(height-1,Math.max(0,Math.round(y*height)))*width+Math.min(width-1,Math.max(0,Math.round(x*width))))*4;return [pixels[i],pixels[i+1],pixels[i+2]]};
  const lum=([r,g,b])=>.2126*r+.7152*g+.0722*b;
  let bg=[];for(let y=.015;y<.95;y+=.014)for(let x=.015;x<.99;x+=.018){if(maskAt(x,y)!==0)continue;let adjacent=true;for(const [dx,dy] of [[.012,0],[-.012,0],[0,.012],[0,-.012]])if(maskAt(x+dx,y+dy)!==0)adjacent=false;if(adjacent)bg.push(rgb(x,y));}
  if(bg.length<60)add('background','White, even background','review','Not enough clear background was found to measure it reliably. Zoom out or use a plain white backdrop.');
  else{const mean=bg.reduce((s,p)=>s+lum(p),0)/bg.length;const white=bg.filter(p=>Math.min(...p)>=225&&Math.max(...p)-Math.min(...p)<=22).length/bg.length;const sd=Math.sqrt(bg.reduce((s,p)=>s+(lum(p)-mean)**2,0)/bg.length);add('background','White, even background',white>=.92&&sd<=14?'pass':'warn',`${Math.round(white*100)}% of sampled background looks near-white; brightness variation ${Math.round(sd)}. ${white>=.92&&sd<=14?'Background looks suitably white and even.':'Use a white backdrop with even lighting; colored areas or shadows were detected.'} (Estimate.)`);}
  if(faces.length!==1){for(const [id,title]of [['framing','Full head & 80–85% coverage'],['center','Centered head'],['pose','Front-facing & level'],['eyes','Eyes open'],['expression','Natural expression'],['lighting','Face lighting'],['redeye','Red-eye screening'],['sharpness','Image sharpness']])add(id,title,'review','Requires one clearly detected face.');return rows;}
  const f=faces[0],chin=f[152],forehead=f[10],left=f[234],right=f[454],fw=Math.abs(right.x-left.x),cx=(left.x+right.x)/2;
  let headTop=1,headCount=0,edge=false;let minX=1,maxX=0;
  for(let my=0;my<maskHeight;my++){let count=0;for(let mx=0;mx<maskWidth;mx++){const xx=mx/maskWidth,yy=my/maskHeight,c=mask[my*maskWidth+mx];if((c===1||c===3||c===5)&&xx>cx-fw*.85&&xx<cx+fw*.85&&yy<chin.y){count++;headCount++;minX=Math.min(minX,xx);maxX=Math.max(maxX,xx);if(mx<2||mx>=maskWidth-2||my<2)edge=true;}}if(count>=Math.max(3,fw*maskWidth*.12))headTop=Math.min(headTop,my/maskHeight);}
  const headReliable=headCount>120&&headTop<forehead.y&&chin.y>headTop;const coverage=(chin.y-headTop)*100;
  add('framing','Full head & 80–85% coverage',!headReliable?'review':edge||chin.y>.98||minX<.015||maxX>.985?'warn':coverage>=80&&coverage<=85?'pass':'warn',!headReliable?'Could not reliably locate the top of the head. Hair, coverings, and the crop can affect this estimate.':edge||chin.y>.98||minX<.015||maxX>.985?'Your head may touch the crop edge. Zoom out to include all hair and the chin.':`Estimated hair-to-chin height is ${coverage.toFixed(1)}% of the photo. ${coverage<80?'Zoom in until the head fills 80–85% of the photo height.':coverage>85?'Zoom out until the head fits within the 80–85% target.':'Within the 80–85% target.'} Segmentation gives an approximate head boundary.`);
  add('center','Centered head',Math.abs(cx-.5)<.04?'pass':'warn',Math.abs(cx-.5)<.04?'Head is horizontally centered.':`Move your photo ${cx<.5?'right':'left'} to center your head.`);
  const eyeA=f[33],eyeB=f[263];const roll=Math.abs(Math.atan2((eyeB.y-eyeA.y)*height,Math.abs(eyeB.x-eyeA.x)*width)*180/Math.PI);const eyeMid=(eyeA.x+eyeB.x)/2,noseOffset=Math.abs(f[1].x-eyeMid)/Math.abs(eyeB.x-eyeA.x);let yaw=0,pitch=0;
  const m=faceResult.facialTransformationMatrixes?.[0]?.data;if(m?.length===16){yaw=Math.abs(Math.asin(Math.max(-1,Math.min(1,m[8])))*180/Math.PI);pitch=Math.abs(Math.atan2(-m[9],m[10])*180/Math.PI);}
  const poseBad=roll>6||noseOffset>.16||yaw>12||pitch>12;add('pose','Front-facing & level',poseBad?'warn':'pass',`Head tilt ${roll.toFixed(0)}°${m?`, turn ${yaw.toFixed(0)}°, vertical angle ${pitch.toFixed(0)}°`:''}. ${poseBad?'Retake the photo looking straight ahead with your head level.':'Pose appears close to straight ahead.'} (Estimate.)`);
  const scores=Object.fromEntries((faceResult.faceBlendshapes?.[0]?.categories||[]).map(b=>[b.categoryName,b.score]));
  const dist=(a,b)=>Math.hypot((a.x-b.x)*width,(a.y-b.y)*height);const ear=(a,b,c,d)=>dist(f[a],f[b])/dist(f[c],f[d]);const openness=Math.min(ear(159,145,33,133),ear(386,374,362,263));
  const blink=Math.max(scores.eyeBlinkLeft||0,scores.eyeBlinkRight||0);add('eyes','Eyes open',blink>.55||openness<.10?'warn':'pass',blink>.55||openness<.10?'One or both eyes may be closed or obscured. Retake with both eyes open and clearly visible.':'Both eyes appear open. Landmark detection cannot rule out hair or glare over the eyes.');
  const smile=Math.max(scores.mouthSmileLeft||0,scores.mouthSmileRight||0),jaw=scores.jawOpen||0;add('expression','Natural expression',!Object.keys(scores).length?'review':smile>.45||jaw>.25?'warn':'pass',!Object.keys(scores).length?'Expression scores unavailable.':smile>.45||jaw>.25?'A strong smile or open mouth was detected. Retake with a relaxed, natural expression.':'No strong smile or open mouth detected. Expression screening is approximate.');
  const patch=(p,r=.022)=>{const values=[];for(let yy=p.y-r;yy<p.y+r;yy+=.004)for(let xx=p.x-r;xx<p.x+r;xx+=.004)if(maskAt(xx,yy)===3)values.push(lum(rgb(xx,yy)));return values};
  const cheeks=[patch(f[50]),patch(f[280])];const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;const skin=[...cheeks[0],...cheeks[1],...patch(f[10])];
  const asymmetry=Math.abs(mean(cheeks[0])-mean(cheeks[1]))/Math.max(25,mean(skin));const clipped=skin.filter(v=>v>250||v<8).length/skin.length;add('lighting','Face lighting',skin.length<25||!cheeks[0].length||!cheeks[1].length?'review':asymmetry>.35||clipped>.12?'warn':'pass',skin.length<25||!cheeks[0].length||!cheeks[1].length?'Not enough visible face skin to assess lighting.':asymmetry>.35||clipped>.12?'Uneven cheek brightness or clipped detail detected. Retake in soft, even light without flash.':'No large cheek-lighting imbalance or severe clipping found. Subtle shadows and reflections may be missed.');
  let eyePixels=0,redPixels=0;for(const center of [f[468],f[473]])if(center)for(let yy=center.y-.008;yy<center.y+.008;yy+=.002)for(let xx=center.x-.009;xx<center.x+.009;xx+=.002){const [r,g,b]=rgb(xx,yy);eyePixels++;if(r>90&&r>g*1.6&&r>b*1.5)redPixels++;}add('redeye','Red-eye screening',!eyePixels?'review':redPixels/eyePixels>.12?'warn':'pass',!eyePixels?'Iris landmarks unavailable.':redPixels/eyePixels>.12?'Red coloration detected around the pupils. Retake without direct flash.':'No obvious red-eye detected in the pupil samples. Small reflections may be missed.');
  // Measure edge detail at a fixed face scale to avoid resolution-dependent thresholds.
  const faceH=chin.y-forehead.y,grid=96;let sum=0,sum2=0,n=0;const val=(gx,gy)=>lum(rgb(cx-fw*.4+(gx/grid)*fw*.8,forehead.y+faceH*.15+(gy/grid)*faceH*.7));for(let gy=1;gy<grid-1;gy++)for(let gx=1;gx<grid-1;gx++){const v=4*val(gx,gy)-val(gx-1,gy)-val(gx+1,gy)-val(gx,gy-1)-val(gx,gy+1);sum+=v;sum2+=v*v;n++;}const variance=sum2/n-(sum/n)**2;add('sharpness','Image sharpness',variance<35?'warn':'pass',variance<35?'The face may be soft or blurred. Use a sharply focused original; enlarging cannot restore detail.':'Face detail appears sufficient in this screening. Fine compression artifacts may be missed.');
  return rows;
}
